import * as React from "react"

import { cn } from "@/lib/utils"

type SkeletonProps = React.ComponentProps<"div"> & {
  /**
   * baseline: the line each row of words will stand on. metrics: the guides a letterer rules before any letter, the
   * baseline and a dotted x-height, measured from the real face. words: each line broken at word spaces, as a layout
   * dummy greeks its text, so the skeleton has the rhythm of a sentence.
   */
  variant?: "baseline" | "metrics" | "words"
}

/**
 * Where the words will be. Still by default; it moves only while an ancestor has aria-busy="true"
 * (and motion is welcome).
 */
function Skeleton({ variant = "baseline", className, ...props }: SkeletonProps) {
  return <div data-slot="skeleton" data-variant={variant} aria-hidden="true" className={cn("db-skeleton", className)} {...props} />
}

type SkeletonLineProps = React.ComponentProps<"i"> & {
  /** Any CSS width; the default is the full line. */
  width?: string
  /** Any CSS height; the default is one line of text. */
  height?: string
  /** Position in the stack, so the stroke reads down the lines in turn. */
  index?: number
}

function SkeletonLine({ width, height, index = 0, className, style, ...props }: SkeletonLineProps) {
  return (
    <i
      data-slot="skeleton-line"
      className={className}
      style={{ "--w": width, "--lh": height, "--i": index, ...style } as React.CSSProperties}
      {...props}
    />
  )
}

/** Where an avatar or a mark will be. */
function SkeletonRing({ size, className, style, ...props }: React.ComponentProps<"span"> & { size?: string }) {
  return (
    <span
      data-slot="skeleton-ring"
      className={cn("db-skeleton-ring", className)}
      style={{ "--s": size, ...style } as React.CSSProperties}
      {...props}
    />
  )
}

export { Skeleton, SkeletonLine, SkeletonRing, type SkeletonProps, type SkeletonLineProps }

@layer components {
  /* ── db-skeleton ── where the words will be: their baselines, their guides, or their rhythm */
  .db-skeleton { display: grid; }
  .db-skeleton > i { position: relative; display: block; width: var(--w, 100%); height: var(--lh, 1.7em); overflow: clip; background: linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 0 100% / 100% var(--db-hairline); }
  .db-skeleton > i::after { content: ""; position: absolute; inset: auto 0 0; height: var(--db-stroke); background: linear-gradient(90deg, transparent, var(--db-pencil) 50%, transparent) no-repeat -60% 0 / 30% 100%; }
  /* While it loads, a pencil stroke reads along each line in turn. */
  [aria-busy="true"] .db-skeleton > i::after { animation: db-read 1600ms var(--db-breath) infinite; animation-delay: calc(var(--i, 0) * 140ms); }
  @keyframes db-read { from { background-position: -60% 0; } to { background-position: 160% 0; } }

  /* Metrics and words size each line as the type it stands for: a line's height sets its font size (a body line is
     1.7em of leading), so a headline's guides and word spaces are a headline's. */
  .db-skeleton:is([data-variant="metrics"], [data-variant="words"]) > i { font-size: calc(var(--lh, 1.7em) / 1.7); height: 1.7em; }

  /* Metrics. From Paul Rand's construction grid: before a letter is drawn, the letterer rules its guides. The baseline in
     a hairline, and above it, one real x-height of the voice (1ex, so it changes with the pair), a dotted line. While it
     loads, the dotted line is ruled out from the start of each line in turn and passes off the far end, then ruled again. */
  @property --db-skeleton-s { syntax: "<percentage>"; inherits: false; initial-value: 100%; }
  @property --db-skeleton-x { syntax: "<percentage>"; inherits: false; initial-value: 0%; }
  .db-skeleton[data-variant="metrics"] > i {
    --db-skeleton-s: 100%; --db-skeleton-x: 0%; --db-skeleton-foot: 0.5em; /* the baseline's height in the line: half the leading plus the descender */
    background:
      linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) 0 calc(100% - var(--db-skeleton-foot)) / 100% var(--db-hairline) no-repeat,
      repeating-linear-gradient(to right, var(--db-rule-strong) 0 1px, transparent 1px 4px) var(--db-skeleton-x) calc(100% - var(--db-skeleton-foot) - 1ex) / var(--db-skeleton-s) var(--db-hairline) no-repeat;
  }
  .db-skeleton[data-variant="metrics"] > i::after { content: none; }
  .db-skeleton[data-variant="metrics"] > i:is([dir="rtl"], [dir="rtl"] *) { --db-skeleton-x: 100%; }
  [aria-busy="true"] .db-skeleton[data-variant="metrics"] > i { animation: db-skeleton-rule 2400ms var(--db-breath) infinite both; animation-delay: calc(var(--i, 0) * 140ms); }
  [aria-busy="true"] .db-skeleton[data-variant="metrics"] > i:is([dir="rtl"], [dir="rtl"] *) { animation-direction: reverse; }
  @keyframes db-skeleton-rule { 0% { --db-skeleton-s: 0%; --db-skeleton-x: 0%; } 45% { --db-skeleton-s: 100%; --db-skeleton-x: 0%; } 70% { --db-skeleton-s: 100%; --db-skeleton-x: 100%; } 100% { --db-skeleton-s: 0%; --db-skeleton-x: 100%; } }

  /* Words. A layout dummy greeks its text as lines broken at word spaces. Two runs of gaps, every 5em and every 7em,
     intersect into words of one to five ems that only repeat after 35, and each line starts the pattern at another place,
     so no two lines share a rhythm. The pencil stroke that reads along the baseline now reads word by word. */
  .db-skeleton[data-variant="words"] > i {
    mask:
      linear-gradient(to right, #000 4.62em, transparent 0) calc(var(--i, 0) * -3em) 0 / 5em 100% repeat-x,
      linear-gradient(to right, #000 6.62em, transparent 0) calc(var(--i, 0) * -1em) 0 / 7em 100% repeat-x;
    mask-composite: intersect;
  }
  .db-skeleton-ring { display: block; width: var(--s, 2.75rem); height: var(--s, 2.75rem); border-radius: 50%; box-shadow: inset 0 0 0 var(--db-hairline) var(--db-rule-strong); }
  /* Forced colours drop the drawn lines unless the skeleton keeps its own, in the system's grey. */
  @media (forced-colors: active) { .db-skeleton, .db-skeleton-ring { forced-color-adjust: none; --db-rule-strong: GrayText; --db-pencil: CanvasText; } }
  @media (prefers-reduced-motion: reduce) { [aria-busy="true"] .db-skeleton[data-variant] > i, [aria-busy="true"] .db-skeleton > i::after { animation: none; } }
}
